    public List<TimeRange> buildTimeRanges(long start, long end) {
        // Check if the start and end times are less than FETCH_DATA_DURATION
        if ((end - start) <= FETCH_DATA_DURATION) {
            return null; // No need to split if duration is less or equal to FETCH_DATA_DURATION
        }

        // Create a list to store the time ranges
        List<TimeRange> timeRanges = new ArrayList<>();

        // Initialize the start times for the time ranges
        for (long t = start; t <= end; t += FETCH_DATA_DURATION) {
            TimeRange timeRange = new TimeRange(t, t + FETCH_DATA_DURATION - 1);
            timeRanges.add(timeRange);
        }

        // Add the last time range if it is not full
        if (timeRanges.get(timeRanges.size() - 1).end < end) {
            timeRanges.add(new TimeRange(timeRanges.get(timeRanges.size() - 1).end, end));
        }

        return timeRanges;
    }
}

