    for (int i = index; i < index + len; i++) {
        int c = str.charAt(i);
        if ((c & 0xC0) == 0x80) {
            // 110xxxxx, 10xxxxxx
            size += 2;
        } else if ((c & 0xE0) == 0xC0) {
            // 1110xxxx, 10xxxxxx, 10xxxxxx
            size += 3;
        } else if ((c & 0xF0) == 0xE0) {
            // 11110xxx, 10xxxxxx, 10xxxxxx, 10xxxxxx
            size += 4;
