public List<Integer> computeUpperBounds(List<K> keys) {
    List<Integer> upperBounds = new ArrayList<>();
    int maxKey = keys.get(0);
    for (K key : keys) {
        if (key.compareTo(maxKey) > 0) {
            maxKey = key;
        }
    }
    for (K key : keys) {
        upperBounds.add(key.compareTo(maxKey) - 1);
    }
    return upperBounds;
}

public static String encodeTemplateNames(String s) {
    StringBuffer encoded = new StringBuffer();
    for (int i = 0; i < s.length(); i++) {
        if (s.charAt(i) == '{') {
            encoded.append("%7B");
        } else if (s.charAt(i) == '}') {
            encoded.append("%7D");
        } else {
            encoded.append(s.charAt(i));
        }
    }
    return encoded.toString();
}

