public static List<ThreadSnapshot> parseFromFileWithTimeRange(File file, List<ProfileAnalyzeTimeRange> timeRanges) throws IOException {
    List<ThreadSnapshot> threadSnapshots = new ArrayList<>();
    try (BufferedReader br = new BufferedReader(new FileReader(file))) {
        String line;
        while ((line = br.readLine()) != null) {
            if (line.startsWith("#")) continue; // Skip comments
            String[] parts = line.split("\\s+");
            if (parts.length != 3) continue; // Ensure correct format

            long timestamp = Long.parseLong(parts[0]);
            String threadName = parts[1];
            String snapshotData = parts[2];

            // Assuming ThreadSnapshot is a custom class with parsing methods
            ThreadSnapshot ts = new ThreadSnapshot();
            ts.setTimestamp(timestamp);
            ts.setName(threadName);
            // Assuming parseSnapshotData is a method to parse snapshot data
            ts.setSnapshotData(parseSnapshotData(snapshotData));
            threadSnapshots.add(ts);
        }
    }
    return threadSnapshots;
}
